#!/bin/sh
# Regenerates src/generated/ from the XSD schemas in concepts/reference/.
#
# Run scripts/fetch-schemas.sh first. The generated files are committed, so this
# only needs running when the codegen or the schemas change; `git diff` after it
# is the review.
set -eu

BASE="$(cd "$(dirname "$0")/.." && pwd)"
OUT="$BASE/src/generated"
BASE_DIR_FOR_SCHEMAS="$BASE"
# shellcheck source=lib/schemas.sh
. "$BASE/scripts/lib/schemas.sh"
SCHEMAS=$(schemas_dir)
CT=urn:iso:std:iso:15118:-20:CommonTypes
# A few xmldsig types are ordinary structs that the V2G schemas reference
# directly (X509IssuerSerial, for one). They go alongside CommonTypes.
DS=http://www.w3.org/2000/09/xmldsig#

run() { cargo run --quiet --manifest-path "$BASE/Cargo.toml" -p iso15118-codegen -- "$@"; }

if [ ! -d "$SCHEMAS/iso15118-2" ]; then
    echo "error: no schemas; run scripts/fetch-schemas.sh first" >&2
    exit 1
fi

# The generated code is only as fixed as its input: refuse a schema that is not
# the one pinned, before codegen reads a byte of it. Imports mean every schema
# set reads several files, so the whole pinned set is checked.
# shellcheck disable=SC2046
verify_schemas $(pinned_schemas) || {
    echo "error: refusing to generate from schemas that do not match their pins" >&2
    exit 1
}

mkdir -p "$OUT/iso20"

echo "ISO 15118-2"
run "$SCHEMAS/iso15118-2/V2G_CI_MsgDef.xsd" --emit -o "$OUT/iso2.rs"

echo "ISO 15118-20"
# CommonTypes is shared by every -20 schema, so it is generated once and the
# others refer to it rather than duplicating a hundred types five times.
run "$SCHEMAS/iso15118-20/V2G_CI_CommonTypes.xsd" --emit --emit-ns "$CT" --emit-ns "$DS" \
    -o "$OUT/iso20/common.rs"
for pair in CommonMessages:messages AC:ac DC:dc WPT:wpt ACDP:acdp; do
    schema=${pair%%:*}
    module=${pair##*:}
    ns="urn:iso:std:iso:15118:-20:$schema"
    run "$SCHEMAS/iso15118-20/V2G_CI_$schema.xsd" --emit \
        --emit-ns "$ns" --extern "$CT=super::common" --extern "$DS=super::common" \
        -o "$OUT/iso20/$module.rs"
done

# Amd 1's AC_DER schemas add members to the AC schema's substitution groups, so
# an AC_DER session's AC messages have a different grammar from a plain AC
# session's. Each variant is therefore one schema set of its own: the AC
# namespace as that schema sees it, plus the DER namespace.
for variant in IEC:ac_der_iec SAE:ac_der_sae; do
    v=${variant%%:*}
    module=${variant##*:}
    run "$SCHEMAS/iso15118-20/V2G_CI_AC_DER_$v.xsd" --emit \
        --emit-ns "urn:iso:std:iso:15118:-20:AC" --emit-ns "urn:iso:std:iso:15118:-20:AC-DER-$v" \
        --extern "$CT=super::common" --extern "$DS=super::common" \
        -o "$OUT/iso20/$module.rs"
done

# The two module indexes are generated too, from the list of schema sets
# above, so `src/generated/` holds nothing written by hand.
cat > "$OUT/mod.rs" <<'RUST'
// @generated by scripts/generate.sh. Do not edit.

//! Message types generated from the V2G XSD schemas.
//!
//! Nothing here is written by hand. `iso15118-codegen` derives every event-code
//! width, enumeration index and field bound from the schemas, cross-checks the
//! result against the EXI reference implementation, and writes these files;
//! `scripts/verify-grammars.sh` re-runs that comparison. `scripts/generate.sh`
//! writes this index and the ISO 15118-20 one.
//!
//! To regenerate:
//!
//! ```sh
//! scripts/fetch-schemas.sh
//! scripts/generate.sh
//! ```

#[cfg(feature = "iso2")]
#[cfg_attr(docsrs, doc(cfg(feature = "iso2")))]
/// ISO 15118-2 message set: one `V2G_Message` root over a body choice of
/// thirty-four messages.
pub mod iso2;

#[cfg(feature = "iso20-common")]
#[cfg_attr(docsrs, doc(cfg(feature = "iso20-common")))]
/// ISO 15118-20 message sets, one module per schema set.
pub mod iso20;
RUST

cat > "$OUT/iso20/mod.rs" <<'RUST'
// @generated by scripts/generate.sh. Do not edit.

//! ISO 15118-20 message types, generated from the V2G XSD schemas.
//!
//! Each of the seven schema sets is its own EXI document with its own document
//! grammar — and its own V2GTP payload type — so each gets a module. They all
//! import `CommonTypes`, which is generated once into
//! [`common`](crate::iso20::common) and referred
//! to from the others, so a `RationalNumber` is the same Rust type everywhere.
//! The two Amd 1 `AC_DER` sets each carry their own copy of the AC messages,
//! because the DER schema extends the AC substitution groups and so changes the
//! AC messages' grammar.
//!
//! | Module | Schema | V2GTP payload type |
//! |---|---|---|
//! | [`messages`](crate::iso20::messages) | `CommonMessages` | `0x8002` |
//! | [`ac`](crate::iso20::ac) | `AC` | `0x8003` |
//! | [`dc`](crate::iso20::dc) | `DC` | `0x8004` |
//! | [`acdp`](crate::iso20::acdp) | `ACDP` | `0x8005` |
//! | [`wpt`](crate::iso20::wpt) | `WPT` | `0x8006` |
//! | [`ac_der_iec`](crate::iso20::ac_der_iec) | `AC` + `AC-DER-IEC` (Amd 1) | `0x8010` |
//! | [`ac_der_sae`](crate::iso20::ac_der_sae) | `AC` + `AC-DER-SAE` (Amd 1) | `0x8011` |

/// Types shared by every ISO 15118-20 schema.
pub mod common;

#[cfg(feature = "iso20-common")]
#[cfg_attr(docsrs, doc(cfg(feature = "iso20-common")))]
/// ISO 15118-20 `CommonMessages`: session setup, authorization, service
/// discovery and selection, schedule exchange, power delivery, session stop.
pub mod messages;

#[cfg(feature = "iso20-ac")]
#[cfg_attr(docsrs, doc(cfg(feature = "iso20-ac")))]
/// ISO 15118-20 AC charging: charge parameter discovery and the AC charge
/// loop, including bidirectional power transfer.
pub mod ac;

#[cfg(feature = "iso20-dc")]
#[cfg_attr(docsrs, doc(cfg(feature = "iso20-dc")))]
/// ISO 15118-20 DC charging: cable check, pre-charge, the DC charge loop and
/// welding detection, including bidirectional power transfer.
pub mod dc;

#[cfg(feature = "iso20-wpt")]
#[cfg_attr(docsrs, doc(cfg(feature = "iso20-wpt")))]
/// ISO 15118-20 wireless power transfer: alignment check, fine positioning
/// and the WPT charge loop.
pub mod wpt;

#[cfg(feature = "iso20-acdp")]
#[cfg_attr(docsrs, doc(cfg(feature = "iso20-acdp")))]
/// ISO 15118-20 automated connection device (pantograph): vehicle
/// positioning, connect and disconnect. A `DC_ACDP` session runs its
/// parameter discovery and charge loop in [`dc`](crate::iso20::dc).
pub mod acdp;

#[cfg(feature = "iso20-ac-der-iec")]
#[cfg_attr(docsrs, doc(cfg(feature = "iso20-ac-der-iec")))]
/// ISO 15118-20 Amd 1 `AC_DER`, IEC variant: the AC messages as
/// `V2G_CI_AC_DER_IEC.xsd` extends them, with the DER members.
pub mod ac_der_iec;

#[cfg(feature = "iso20-ac-der-sae")]
#[cfg_attr(docsrs, doc(cfg(feature = "iso20-ac-der-sae")))]
/// ISO 15118-20 Amd 1 `AC_DER`, SAE variant: the AC messages as
/// `V2G_CI_AC_DER_SAE.xsd` extends them, with the DER members.
pub mod ac_der_sae;
RUST

cargo fmt --manifest-path "$BASE/Cargo.toml" --all
echo "done."
